            if "demand" in val and nid not in dem: dem[nid] = val["demand"]
            if "x" in val and "y" in val and nid not in coords: coords[nid] = (val["x"], val["y"])
        elif isinstance(val, (list, tuple)):
            if len(val) >= 3 and nid not in dem: dem[nid] = val[-1]
            if len(val) >= 4 and nid not in coords: coords[nid] = (val[1], val[2])
    if not cust:
        cust = [i for i in set(coords) | set(dem) if i != dep]
        cust.sort(key=lambda x: str(x))
    for i in cust:
        if i not in dem: dem[i] = 1
    if dep not in coords: coords[dep] = (0.0, 0.0)
    if cap is None: cap = sum(dem[i] for i in cust)
    dx0, dy0 = coords[dep]
    def dist(a, b):
        x1, y1 = coords[a]; x2, y2 = coords[b]
        dx = x1 - x2; dy = y1 - y2
        return (dx * dx + dy * dy) ** 0.5
    def key(i):
        x, y = coords[i]; dx = x - dx0; dy = y - dy0
        return (0 if dy >= 0 else 1, dx / (abs(dx) + abs(dy) + 1e-12), dx * dx + dy * dy, str(i))
    order = sorted(cust, key=key)
    routes = []; r = []; load = 0
    for i in order:
        d = dem[i]
        if d > cap:
            if r: routes.append(r); r = []; load = 0
            routes.append([i])
        elif load + d <= cap:
            r.append(i); load += d
        else:
            routes.append(r); r = [i]; load = d
    if r: routes.append(r)
    def rload(rt): return sum(dem[i] for i in rt)
    def rcost(rt):
        if not rt: return 0.0
        s = dist(dep, rt[0]) + dist(rt[-1], dep)
        for i in range(len(rt) - 1): s += dist(rt[i], rt[i + 1])
        return s
    def opt(rt):
        rt = rt[:]
        n = len(rt)
        if n < 4: return rt
        ok = True
        while ok:
            ok = False
            for i in range(n - 2):
                a = dep if i == 0 else rt[i - 1]
                b = rt[i]
                for j in range(i + 2, n):
                    c = rt[j - 1]
                    d = dep if j == n else rt[j]
                    if dist(a, b) + dist(c, d) > dist(a, c) + dist(b, d) + 1e-12:
                        rt[i:j] = rt[i:j][::-1]
                        ok = True
                        break
                if ok: break
        return rt
    routes = [opt(x) for x in routes if x]
    changed = True
    while changed:
        changed = False
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                A, B = routes[i], routes[j]
                la, lb = rload(A), rload(B)
                for a, na in enumerate(A):
                    da = dem[na]
                    pa = dep if a == 0 else A[a - 1]
                    xa = dep if a == len(A) - 1 else A[a + 1]
                    ra = dist(pa, na) + dist(na, xa) - dist(pa, xa)
                    for b, nb in enumerate(B):
                        db = dem[nb]
                        if la - da + db > cap or lb - db + da > cap: 
                            continue
                        pb = dep if b == 0 else B[b - 1]
                        xb = dep if b == len(B) - 1 else B[b + 1]
                        rb = dist(pb, nb) + dist(nb, xb) - dist(pb, xb)
                        ia = dist(pa, nb) + dist(nb, xa) - dist(pa, xa)
                        ib = dist(pb, na) + dist(na, xb) - dist(pb, xb)
                        if ra + rb > ia + ib + 1e-12:
                            A[a], B[b] = nb, na
                            changed = True
                            break
                    if changed: break
                if changed: break
            if changed: break
    for _ in range(2):
        for k in range(len(routes)):
            routes[k] = opt(routes[k])
    seen = {}
    for rt in routes:
        for i in rt: seen[i] = seen.get(i, 0) + 1
    miss = [i for i in cust if seen.get(i, 0) == 0]
    if miss:
        for i in miss:
            best = 0
            bd = None
            for rti, rt in enumerate(routes):
                if rload(rt) + dem[i] > cap: 
                    continue
                for p in range(len(rt) + 1):
                    a = dep if p == 0 else rt[p - 1]
                    b = dep if p == len(rt) else rt[p]
                    v = dist(a, i) + dist(i, b) - dist(a, b)
                    if bd is None or v < bd:
                        bd = v; best = (rti, p)
            if bd is None:
                routes.append([i])
            else:
                rti, p = best
                routes[rti].insert(p, i)
    out = []
    for rt in routes:
        if rt:
            out.append(rt)
    return out
